using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD intrinsics to process multiple elements per cycle.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        ref float start = ref MemoryMarshal.GetReference(values);
        int length = values.Length;

        if (Vector256.IsHardwareAccelerated && length >= Vector256<float>.Count * 2)
        {
            return FindMinMaxVector256(ref start, length);
        }

        if (Vector128.IsHardwareAccelerated && length >= Vector128<float>.Count * 2)
        {
            return FindMinMaxVector128(ref start, length);
        }

        return FindMinMaxScalar(ref start, length);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxVector256(ref float start, int length)
    {
        int vectorSize = Vector256<float>.Count;
        ref float ptr = ref start;

        // Use two accumulators to enable instruction-level parallelism
        var vMin0 = Vector256.LoadUnsafe(ref ptr);
        var vMax0 = vMin0;
        var vMin1 = Vector256.LoadUnsafe(ref ptr, (nuint)vectorSize);
        var vMax1 = vMin1;

        int i = vectorSize * 2;
        int limit = length - (vectorSize * 2 - 1);

        while (i < limit)
        {
            var v0 = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            var v1 = Vector256.LoadUnsafe(ref ptr, (nuint)(i + vectorSize));
            vMin0 = Vector256.Min(vMin0, v0);
            vMax0 = Vector256.Max(vMax0, v0);
            vMin1 = Vector256.Min(vMin1, v1);
            vMax1 = Vector256.Max(vMax1, v1);
            i += vectorSize * 2;
        }

        // Process any remaining full vector
        if (i + vectorSize <= length)
        {
            var v = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            vMin0 = Vector256.Min(vMin0, v);
            vMax0 = Vector256.Max(vMax0, v);
            i += vectorSize;
        }

        // Merge accumulators
        vMin0 = Vector256.Min(vMin0, vMin1);
        vMax0 = Vector256.Max(vMax0, vMax1);

        // Horizontal reduce: narrow 256 → 128 → scalar
        var loMin = vMin0.GetLower();
        var hiMin = vMin0.GetUpper();
        var rMin = Vector128.Min(loMin, hiMin);

        var loMax = vMax0.GetLower();
        var hiMax = vMax0.GetUpper();
        var rMax = Vector128.Max(loMax, hiMax);

        float min = HorizontalMin128(rMin);
        float max = HorizontalMax128(rMax);

        // Scalar tail
        for (; i < length; i++)
        {
            float v = Unsafe.Add(ref ptr, i);
            if (v < min) min = v;
            if (v > max) max = v;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxVector128(ref float start, int length)
    {
        int vectorSize = Vector128<float>.Count;
        ref float ptr = ref start;

        var vMin = Vector128.LoadUnsafe(ref ptr);
        var vMax = vMin;
        var vMin1 = Vector128.LoadUnsafe(ref ptr, (nuint)vectorSize);
        var vMax1 = vMin1;

        int i = vectorSize * 2;
        int limit = length - (vectorSize * 2 - 1);

        while (i < limit)
        {
            var v0 = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var v1 = Vector128.LoadUnsafe(ref ptr, (nuint)(i + vectorSize));
            vMin = Vector128.Min(vMin, v0);
            vMax = Vector128.Max(vMax, v0);
            vMin1 = Vector128.Min(vMin1, v1);
            vMax1 = Vector128.Max(vMax1, v1);
            i += vectorSize * 2;
        }

        if (i + vectorSize <= length)
        {
            var v = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            vMin = Vector128.Min(vMin, v);
            vMax = Vector128.Max(vMax, v);
            i += vectorSize;
        }

        vMin = Vector128.Min(vMin, vMin1);
        vMax = Vector128.Max(vMax, vMax1);

        float min = HorizontalMin128(vMin);
        float max = HorizontalMax128(vMax);

        for (; i < length; i++)
        {
            float v = Unsafe.Add(ref ptr, i);
            if (v < min) min = v;
            if (v > max) max = v;
        }

        return (min, max);
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMin128(Vector128<float> v)
    {
        // Shuffle and reduce: 4 floats → 1
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Min(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Min(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static float HorizontalMax128(Vector128<float> v)
    {
        var shuf = Vector128.Shuffle(v, Vector128.Create(2, 3, 0, 1));
        v = Vector128.Max(v, shuf);
        shuf = Vector128.Shuffle(v, Vector128.Create(1, 0, 3, 2));
        v = Vector128.Max(v, shuf);
        return v.ToScalar();
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static (float Min, float Max) FindMinMaxScalar(ref float start, int length)
    {
        float min = start;
